// Estilos de letra, colores e imagen del logotipo para el certificado de capacidad financiera

const Estiloscertificado = "\n/* Diseño en tamaño carta para el certificado de capacidad financiera de MiTecho */\n:root{\n  /* Colores principales de la marca */\n  --mitecho-acento:#D4FF3A;      /* Lima */\n  --mitecho-azul:#1E345B;        /* Azul Banco */\n  --mitecho-azul-oscuro:#0B1A39; /* Azul Noche */\n  --mitecho-naranja:#FF6A2B;     /* Alerta */\n  --mitecho-dorado:#FFD23F;      /* Avisos */\n  --mitecho-oliva:#4E6E00;       /* Acento sobre fondos claros */\n  --mitecho-fondo:#0B0C0A;       /* Fondo oscuro */\n  --mitecho-tarjeta:#16180F;     /* Fondo de tarjeta */\n  --mitecho-sub:#24271C;         /* Fondo interno */\n  --mitecho-texto:#F2F4EC;       /* Blanco hueso */\n  --mitecho-gris:#A3A898;        /* Texto secundario */\n  --mitecho-tenue:#6F7466;       /* Líneas suaves */\n\n  /* Superficies claras del papel */\n  --papel:#F2F4EC;\n  --papel-alto:#F9FAF5;\n  --tinta:#0B0C0A;\n  --tinta-2:#3A3E32;\n  --tinta-3:#5E6356;\n  --linea:#D6DACB;\n  --linea-fuerte:#B7BCAA;\n\n  /* Cada solicitante tiene su color en todo el documento */\n  --p1:var(--mitecho-azul);\n  --p2:var(--mitecho-oliva);\n\n  --f-display:'Familjen Grotesk','Hanken Grotesk',sans-serif;\n  --f-texto:'Hanken Grotesk',system-ui,sans-serif;\n  --f-mono:'IBM Plex Mono',ui-monospace,monospace;\n\n  --margen:48px;\n}\n\n*,*::before,*::after{box-sizing:border-box}\nhtml,body{margin:0}\nbody{\n  background:var(--mitecho-fondo);\n  color:var(--tinta);\n  font:400 12px/1.45 var(--f-texto);\n  -webkit-font-smoothing:antialiased;\n  -webkit-print-color-adjust:exact;\n  print-color-adjust:exact;\n  font-variant-numeric:tabular-nums;\n}\nh1,h2,h3,p,dl,dd,ol,ul,figure{margin:0}\nol,ul{padding:0;list-style:none}\n.mono{font-family:var(--f-mono);font-weight:500;letter-spacing:-.01em}\n\n/* Contenedor de las hojas en pantalla */\n.doc{\n  display:grid;\n  justify-content:center;\n  gap:36px;\n  padding:40px 16px 64px;\n}\n.hoja{\n  position:relative;\n  width:8.5in;\n  height:11in;\n  overflow:hidden;\n  background:var(--papel);\n  display:flex;\n  flex-direction:column;\n  box-shadow:0 1px 0 rgba(255,255,255,.06),0 28px 70px rgba(0,0,0,.55);\n  zoom:var(--z,1);\n}\n\n/* Primera hoja del certificado */\n.plano{\n  position:relative;\n  color:var(--mitecho-texto);\n  padding:14px var(--margen) 20px;\n  background:\n    linear-gradient(rgba(242,244,236,.055) 1px,transparent 1px) 0 0/120px 120px,\n    linear-gradient(90deg,rgba(242,244,236,.055) 1px,transparent 1px) 0 0/120px 120px,\n    linear-gradient(rgba(242,244,236,.028) 1px,transparent 1px) 0 0/24px 24px,\n    linear-gradient(90deg,rgba(242,244,236,.028) 1px,transparent 1px) 0 0/24px 24px,\n    linear-gradient(158deg,var(--mitecho-azul) 0%,var(--mitecho-azul-oscuro) 72%);\n}\n.plano__top{\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-start;\n  gap:24px;\n}\n.marca{display:flex;align-items:center;gap:12px}\n.marca img{width:52px;height:auto;display:block}\n.marca__nombre{\n  display:block;\n  font:700 25px/1 var(--f-display);\n  letter-spacing:-.02em;\n}\n.marca__doc{\n  display:block;\n  margin-top:5px;\n  font:600 12.5px/1.2 var(--f-texto);\n  color:var(--mitecho-gris);\n}\n\n/* Cajetín: el rótulo de un plano arquitectónico */\n.cajetin{\n  display:grid;\n  grid-template-columns:repeat(3,auto);\n  border:1px solid rgba(242,244,236,.24);\n  border-radius:3px;\n  background:rgba(11,26,57,.55);\n}\n.cajetin div{\n  padding:6px 11px 7px;\n  border-right:1px solid rgba(242,244,236,.16);\n  border-bottom:1px solid rgba(242,244,236,.16);\n}\n.cajetin div:nth-child(3n){border-right:0}\n.cajetin div:nth-last-child(-n+3){border-bottom:0}\n.cajetin dt{\n  font:600 9.5px/1.2 var(--f-texto);\n  color:var(--mitecho-gris);\n}\n.cajetin dd{\n  margin-top:2px;\n  font:500 11px/1.25 var(--f-mono);\n  color:var(--mitecho-texto);\n  white-space:nowrap;\n}\n\n.plano__frase{\n  margin-top:14px;\n  font:400 18px/1.3 var(--f-texto);\n  color:var(--mitecho-texto);\n}\n.plano__cifra{\n  display:flex;\n  align-items:baseline;\n  margin-top:2px;\n  font:700 86px/.92 var(--f-display);\n  letter-spacing:-.045em;\n  color:var(--mitecho-acento);\n}\n.plano__cifra .moneda{\n  font-size:48px;\n  align-self:flex-start;\n  margin:9px 6px 0 0;\n  letter-spacing:0;\n}\n.plano__cifra .unidad{\n  margin-left:16px;\n  font:600 30px/1 var(--f-display);\n  letter-spacing:-.02em;\n  color:var(--mitecho-texto);\n}\n\n/* Cota: la composición del precio dibujada como una medida de plano */\n.cota{margin-top:18px}\n.cota svg{display:block;width:100%;height:auto;overflow:visible}\n.cota__txt{font:500 10.5px var(--f-mono);fill:var(--mitecho-gris)}\n.cota__pct{font:600 11px var(--f-mono);fill:var(--mitecho-texto)}\n.cota__leyenda{\n  display:grid;\n  grid-template-columns:80fr 20fr;\n  gap:4px;\n  margin-top:9px;\n}\n.cota__leyenda p{font-size:11px;color:var(--mitecho-gris);line-height:1.35}\n.cota__leyenda strong{\n  display:block;\n  font:600 14px/1.2 var(--f-mono);\n  color:var(--mitecho-texto);\n}\n.cota__leyenda p:last-child strong{color:var(--mitecho-acento)}\n\n.plano__datos{\n  display:grid;\n  grid-template-columns:1.05fr 1fr 1fr;\n  margin-top:16px;\n  border-top:1px solid rgba(242,244,236,.18);\n}\n.plano__datos li{padding:11px 16px 0 0}\n.plano__datos li + li{padding-left:16px;border-left:1px solid rgba(242,244,236,.12)}\n.plano__datos span{display:block;font-size:11px;color:var(--mitecho-gris)}\n.plano__datos strong{\n  display:block;\n  margin:3px 0 2px;\n  font:600 21px/1.1 var(--f-display);\n  letter-spacing:-.015em;\n  color:var(--mitecho-texto);\n}\n.plano__datos small{font-size:11px;color:var(--mitecho-gris)}\n\n/* Cuerpo sobre fondo claro */\n.cuerpo{\n  flex:1;\n  padding:14px var(--margen) 0;\n}\n.bloque + .bloque{margin-top:9px}\n.bloque__cab{\n  display:flex;\n  justify-content:space-between;\n  align-items:baseline;\n  gap:20px;\n  margin-bottom:10px;\n}\n.bloque__cab h2{\n  font:600 18px/1.2 var(--f-display);\n  letter-spacing:-.01em;\n}\n.bloque__cab p{font-size:11.5px;color:var(--tinta-3);text-align:right}\n\n/* Solicitantes */\n.solicitantes{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:14px;\n}\n.persona{\n  --c:var(--p1);\n  position:relative;\n  background:var(--papel-alto);\n  border:1px solid var(--linea);\n  border-radius:12px;\n  padding:12px 16px 10px;\n  overflow:hidden;\n}\n.persona::before{\n  content:\"\";\n  position:absolute;inset:0 auto 0 0;\n  width:4px;\n  background:var(--c);\n}\n.persona--2{--c:var(--p2)}\n.persona__rol{\n  display:flex;align-items:center;gap:7px;\n  font:600 11px/1 var(--f-texto);\n  color:var(--c);\n}\n.persona__rol .mono{\n  padding:3px 6px;\n  border-radius:4px;\n  background:var(--c);\n  color:var(--mitecho-texto);\n  font-size:10px;\n}\n.persona h3{\n  margin-top:7px;\n  font:600 19px/1.15 var(--f-display);\n  letter-spacing:-.015em;\n}\n.persona__perfil{margin-top:2px;font-size:11.5px;color:var(--tinta-3)}\n.cuentas{margin-top:8px}\n.cuentas div{\n  display:flex;justify-content:space-between;gap:12px;\n  padding:3px 0;\n  border-top:1px dashed var(--linea);\n}\n.cuentas dt{color:var(--tinta-2)}\n.cuentas dd{font:500 12px var(--f-mono);color:var(--tinta)}\n.cuentas .menos dd{color:#B23F0A}\n.cuentas .vacio dd{color:var(--mitecho-tenue)}\n.cuentas .total{border-top:1px solid var(--linea-fuerte)}\n.cuentas .total dt{font-weight:600;color:var(--tinta)}\n.cuentas .total dd{font-weight:600}\n.persona__cab{display:flex;justify-content:space-between;align-items:center;gap:12px}\n.aporte{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--tinta-3);white-space:nowrap}\n.aporte__barra{\n  width:64px;height:6px;border-radius:3px;\n  background:var(--linea);\n  overflow:hidden;\n}\n.aporte__barra i{display:block;height:100%;background:var(--c);border-radius:3px}\n.aporte b{color:var(--c);font-weight:600}\n\n/* Ecuación del hogar */\n.ecuacion{\n  display:grid;\n  grid-template-columns:1fr auto 1fr auto 1fr auto .62fr 1.1fr;\n  align-items:stretch;\n  border:1px solid var(--linea-fuerte);\n  border-radius:12px;\n  background:var(--papel-alto);\n  overflow:hidden;\n}\n.ecuacion > div{padding:11px 12px 10px}\n.ecuacion > span{\n  display:grid;place-items:center;\n  width:22px;\n  font:600 18px/1 var(--f-display);\n  color:var(--mitecho-tenue);\n}\n.ecuacion small{display:block;font-size:10.5px;line-height:1.25;color:var(--tinta-3)}\n.ecuacion strong{display:block;margin-top:5px;font:600 14px/1 var(--f-mono)}\n.ecuacion:not(.ecuacion--individual){grid-template-columns:1fr auto 1fr auto 1fr auto 1fr auto .62fr 1.1fr}\n.ecuacion .resultado{\n  background:var(--mitecho-acento);\n  border-left:1px solid var(--linea-fuerte);\n}\n.ecuacion .resultado small{color:var(--mitecho-sub)}\n.ecuacion .resultado strong{font:700 19px/1 var(--f-display);letter-spacing:-.01em;margin-top:4px}\n.nota-calculo{margin-top:7px;font-size:11px;color:var(--tinta-3)}\n\n/* Medidores */\n.medidores{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:22px;\n  margin-top:14px;\n}\n.medidor__cab{display:flex;justify-content:space-between;align-items:baseline;gap:8px}\n.medidor__cab span{font-size:11px;font-weight:600;color:var(--tinta-2)}\n.medidor__cab strong{font:700 18px/1 var(--f-display)}\n.medidor__pista{\n  position:relative;\n  height:8px;margin-top:6px;\n  border-radius:4px;\n  background:var(--linea);\n}\n.medidor__pista i{position:absolute;inset:0 auto 0 0;border-radius:4px;background:var(--mitecho-azul)}\n.medidor__pista b{\n  position:absolute;top:-4px;bottom:-4px;width:2px;margin-left:-1px;\n  background:var(--tinta);\n}\n.medidor p{margin-top:6px;font-size:10.5px;color:var(--tinta-3)}\n\n/* Pie de página */\n.pie{\n  display:flex;justify-content:space-between;align-items:center;gap:16px;\n  margin:0 var(--margen);\n  padding:10px 0 16px;\n  border-top:1px solid var(--linea);\n  font-size:10px;\n  color:var(--tinta-3);\n}\n.pie .mono{font-size:10px;color:var(--tinta-2)}\n.pie__ref{display:flex;gap:14px}\n\n/* Segunda hoja del certificado */\n.franja{\n  display:flex;justify-content:space-between;align-items:center;\n  padding:12px var(--margen);\n  color:var(--mitecho-texto);\n  background:\n    linear-gradient(90deg,rgba(242,244,236,.028) 1px,transparent 1px) 0 0/24px 24px,\n    linear-gradient(158deg,var(--mitecho-azul) 0%,var(--mitecho-azul-oscuro) 80%);\n}\n.franja .marca img{width:34px}\n.franja .marca__nombre{font-size:17px}\n.franja .marca__doc{margin-top:3px;font-size:11px}\n.franja__ref{font:400 11px/1.45 var(--f-texto);color:var(--mitecho-gris);text-align:right}\n.franja__ref b{font:600 11px/1.45 var(--f-mono);color:var(--mitecho-texto)}\n\n.estado-cierre{\n  display:inline-flex;align-items:center;gap:6px;\n  padding:4px 10px 4px 8px;\n  border-radius:999px;\n  background:var(--mitecho-acento);\n  font:600 11px/1 var(--f-texto);\n  color:var(--tinta);\n  white-space:nowrap;\n}\n.estado-cierre svg{width:12px;height:12px}\n\n.resumen-cierre{font-size:12.5px;line-height:1.5;color:var(--tinta-2);max-width:84ch;margin:-2px 0 10px}\n.resumen-cierre strong{color:var(--tinta);font-weight:600}\n\n/* Cascada del cierre financiero */\n.cascada{\n  border:1px solid var(--linea);\n  border-radius:12px;\n  background:var(--papel-alto);\n  padding:4px 16px 8px;\n}\n.cascada__fila{\n  display:grid;\n  grid-template-columns:214px 1fr 112px;\n  align-items:center;\n  gap:14px;\n  min-height:22px;\n}\n.cascada__fila + .cascada__fila{border-top:1px dashed var(--linea)}\n.cascada__fila.suma{border-top:1px solid var(--linea-fuerte)}\n.cascada__fila dt{font-size:11.5px;color:var(--tinta-2);line-height:1.25}\n.cascada__fila dt .op{display:inline-block;width:14px;font-family:var(--f-mono);color:var(--mitecho-tenue)}\n.cascada__fila.suma dt{font-weight:600;color:var(--tinta)}\n.cascada__fila dd:last-child{text-align:right;font:500 12px var(--f-mono)}\n.cascada__fila.suma dd:last-child{font-weight:600}\n.cascada__fila.resta dd:last-child{color:#B23F0A}\n.cascada__fila.nulo dd{color:var(--mitecho-tenue)}\n.pista{\n  position:relative;height:14px;\n  background:\n    linear-gradient(90deg,var(--linea) 1px,transparent 1px) 0 0/calc(100%/7) 100%;\n  border-right:1px solid var(--linea);\n}\n.pista i{position:absolute;top:1px;bottom:1px;border-radius:2px}\n.pista em{font-style:normal;font-size:10.5px;color:var(--mitecho-tenue);position:absolute;left:4px;top:0;line-height:14px;background:var(--papel-alto);padding-right:4px}\n.eje{\n  display:grid;grid-template-columns:214px 1fr 112px;gap:14px;\n  padding:4px 0 1px;\n}\n.eje ol{position:relative;height:14px;font:500 9.5px/14px var(--f-mono);color:var(--mitecho-tenue)}\n.eje li{position:absolute;top:0;transform:translateX(-50%)}\n.eje span{font-size:10px;color:var(--mitecho-tenue);text-align:right}\n.c-p1{background:var(--p1)}\n.c-p2{background:var(--p2)}\n.c-caja{background:var(--mitecho-tarjeta)}\n.c-total{background:var(--tinta-2)}\n.c-cuota{background:var(--mitecho-acento);box-shadow:inset 0 0 0 1px rgba(11,12,10,.35)}\n.c-gastos{background:repeating-linear-gradient(135deg,var(--mitecho-tenue) 0 2px,transparent 2px 5px);box-shadow:inset 0 0 0 1px var(--mitecho-tenue)}\n.c-margen{background:var(--mitecho-acento);box-shadow:inset 0 0 0 1.5px var(--tinta)}\n\n/* Tarjeta de la Caja de Compensación */\n.caja{\n  position:relative;\n  background:var(--mitecho-tarjeta);\n  color:var(--mitecho-texto);\n  border-radius:16px;\n  padding:15px 20px 13px;\n  overflow:hidden;\n}\n.caja::after{\n  /* retícula sutil, eco del plano de la portada */\n  content:\"\";position:absolute;inset:0;pointer-events:none;\n  background:\n    linear-gradient(rgba(212,255,58,.04) 1px,transparent 1px) 0 0/24px 24px,\n    linear-gradient(90deg,rgba(212,255,58,.04) 1px,transparent 1px) 0 0/24px 24px;\n  -webkit-mask-image:linear-gradient(100deg,transparent 35%,#000 100%);\n          mask-image:linear-gradient(100deg,transparent 35%,#000 100%);\n}\n.caja__grid{\n  position:relative;z-index:1;\n  display:grid;\n  grid-template-columns:1.15fr 1.1fr .85fr;\n  gap:20px;\n  align-items:start;\n}\n.caja__entidad{display:flex;gap:12px;align-items:center}\n.caja__logo{\n  /* Espacio para el logo oficial de la Caja (si existe autorización de uso) */\n  flex:none;\n  display:grid;place-items:center;\n  width:50px;height:50px;\n  border-radius:12px;\n  background:var(--mitecho-sub);\n  border:1px solid rgba(212,255,58,.35);\n  font:700 18px/1 var(--f-display);\n  color:var(--mitecho-acento);\n  letter-spacing:-.02em;\n}\n.caja__entidad h3{font:600 22px/1.1 var(--f-display);letter-spacing:-.015em}\n.caja__entidad p{margin-top:3px;font-size:11px;color:var(--mitecho-gris);line-height:1.35}\n.caja__dato > span{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--mitecho-gris)}\n.caja__dato strong{\n  display:block;margin-top:6px;\n  font:700 27px/1 var(--f-display);\n  letter-spacing:-.025em;\n}\n.caja__dato small{display:block;margin-top:5px;font-size:11px;color:var(--mitecho-gris)}\n.caja__dato--subsidio strong{color:var(--mitecho-acento)}\n.chip{\n  display:inline-block;\n  padding:3px 8px;\n  border-radius:999px;\n  font:600 10.5px/1.2 var(--f-texto);\n}\n.chip--asignado{background:var(--mitecho-acento);color:var(--tinta)}\n.chip--estudio{background:var(--mitecho-dorado);color:var(--tinta)}\n.chip--no-aplica{background:var(--mitecho-sub);color:var(--mitecho-gris)}\n\n.pasos{\n  position:relative;z-index:1;\n  display:grid;grid-template-columns:repeat(4,1fr);\n  margin-top:13px;padding-top:11px;\n  border-top:1px solid rgba(242,244,236,.1);\n}\n.paso{position:relative;padding-right:10px}\n.paso::before{\n  /* tramo de línea hacia el siguiente paso */\n  content:\"\";position:absolute;left:18px;right:2px;top:7px;height:2px;\n  background:var(--mitecho-sub);\n}\n.paso:last-child::before{display:none}\n.paso.hecho::before{background:var(--mitecho-acento)}\n.paso.hecho:has(+ .pendiente)::before{background:var(--mitecho-sub)}\n.paso i{\n  position:relative;z-index:1;\n  display:grid;place-items:center;\n  width:16px;height:16px;border-radius:50%;\n  border:2px solid var(--mitecho-tenue);\n  background:var(--mitecho-tarjeta);\n}\n.paso.hecho i{background:var(--mitecho-acento);border-color:var(--mitecho-acento)}\n.paso.hecho i svg{width:9px;height:9px}\n.paso b{display:block;margin-top:7px;font:600 11.5px/1.2 var(--f-texto)}\n.paso span{display:block;margin-top:1px;font-size:10.5px;color:var(--mitecho-gris)}\n.paso.pendiente b{color:var(--mitecho-gris)}\n\n/* Tabla de deudas por solicitante */\n.deudas{\n  width:100%;\n  border-collapse:collapse;\n  font-size:11.5px;\n}\n.deudas th,.deudas td{padding:3.5px 8px;text-align:left;vertical-align:middle}\n.deudas thead th{\n  font:600 10.5px/1.2 var(--f-texto);\n  color:var(--tinta-3);\n  border-bottom:1px solid var(--linea-fuerte);\n  padding-top:0;padding-bottom:5px;\n}\n.deudas .num{text-align:right;font:500 11.5px var(--f-mono);white-space:nowrap}\n.deudas thead .num{font:600 10.5px/1.2 var(--f-texto)}\n.deudas td:first-child,.deudas th:first-child{padding-left:12px}\n.deudas tbody tr:not(.titular) td{border-bottom:1px dashed var(--linea);color:var(--tinta-2)}\n.deudas tbody tr:not(.titular) .num{color:var(--tinta)}\n.deudas .titular th,.deudas .titular td{\n  padding-top:7px;\n  border-bottom:1px solid var(--linea);\n  font-weight:600;\n}\n.deudas .titular th{font:600 12px/1.2 var(--f-texto)}\n.deudas .titular th i{display:inline-block;width:9px;height:9px;margin-right:8px;border-radius:2px;background:var(--c);vertical-align:0}\n.deudas .titular th small{margin-left:6px}\n.deudas .titular .num{font-weight:600;color:var(--c)}\n.deudas .titular small{font-weight:400;color:var(--tinta-3);font-size:11px}\n.deudas tbody.p1{--c:var(--p1)}\n.deudas tbody.p2{--c:var(--p2)}\n.deudas tr.excluida td{color:var(--mitecho-tenue)!important;text-decoration:none}\n.deudas tr.excluida td:first-child span{text-decoration:line-through;text-decoration-color:var(--linea-fuerte)}\n.deudas tfoot th,.deudas tfoot td{\n  padding-top:6px;\n  border-top:1.5px solid var(--tinta);\n  font-weight:600;\n}\n.deudas tfoot .num{font-weight:600}\n.estado{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}\n.estado::before{content:\"\";width:8px;height:8px;border-radius:50%;background:var(--mitecho-naranja)}\n.estado--excluida::before{background:transparent;box-shadow:inset 0 0 0 1.5px var(--mitecho-tenue)}\n\n/* Nota legal + verificación */\n.legal{\n  display:grid;\n  grid-template-columns:1fr 84px;\n  gap:20px;\n  align-items:start;\n  padding:12px 0 0;\n  border-top:1px solid var(--linea);\n}\n.legal h2{font:600 12px/1.2 var(--f-display);margin-bottom:4px}\n.legal p{\n  column-count:2;column-gap:22px;column-fill:balance;\n  font-size:10px;line-height:1.45;color:var(--tinta-3);\n}\n.verifica{text-align:center;align-self:center}\n\n/* Leyenda de simulación arriba de cada hoja */\n.aviso-simulacion{\n  margin:0;\n  padding:6px 18px;\n  background:#FFF4D6;\n  border-bottom:1px solid #E8C96A;\n  color:#5A4300;\n  font-size:9.5px;\n  line-height:1.35;\n  font-weight:600;\n  text-align:center;\n  flex:none;\n}\n\n/* Lista de documentos que pide el banco en la hoja 3 */\n.documentos{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:2px 24px;\n  margin:4px 0 0;\n  padding-left:0;\n  font-size:10.5px;\n  line-height:1.45;\n  color:var(--tinta-2);\n}\n.documentos li{margin:0}\n.documentos-nota{margin:4px 0 0;font-size:10px;line-height:1.4;color:var(--tinta-3)}\n.verifica svg{display:block;width:72px;height:72px;margin:0 auto;fill:var(--tinta)}\n.verifica span{display:block;margin-top:6px;font-size:9.5px;line-height:1.3;color:var(--tinta-3)}\n.verifica .mono{font-size:9.5px;color:var(--tinta-2)}\n\n\n/* Tercera hoja con guía de lectura */\n.eje .eje__guia{text-align:left;color:var(--mitecho-oliva);font-weight:600}\n.guia__titulo{font:700 27px/1.05 var(--f-display);letter-spacing:-.025em}\n.guia__lead{margin-top:6px;font-size:13px;line-height:1.5;color:var(--tinta-2)}\n.guia__pregunta{margin:-2px 0 11px;font-size:12.5px;line-height:1.5;color:var(--tinta-2)}\n.guia__pregunta strong{color:var(--tinta);font-weight:600}\n.bloque__cab .guia__hoja{\n  font:500 10.5px/1 var(--f-mono);\n  color:var(--mitecho-texto);\n  background:var(--mitecho-azul);\n  padding:4px 8px;border-radius:4px;\n}\n\n/* Cascada anotada: la misma gráfica de la hoja 2, con una nota por paso */\n.lectura{\n  border:1px solid var(--linea);\n  border-radius:12px;\n  background:var(--papel-alto);\n  padding:4px 16px 4px;\n}\n.lectura__paso,.lectura__cab{\n  display:grid;\n  grid-template-columns:24px 1fr 250px;\n  gap:16px;\n  align-items:start;\n}\n.lectura__paso{padding:7px 0}\n.lectura__paso + .lectura__paso{border-top:1px solid var(--linea-fuerte)}\n.lectura__cab{padding:5px 0 0}\n.lectura__cab span{font-size:10px;color:var(--mitecho-tenue)}\n.lectura .cascada__fila,.lectura .eje{grid-template-columns:128px 1fr 58px;gap:10px}\n.lectura .eje{padding:0}\n.lectura .cascada__fila dd:last-child{font-size:11.5px}\n.lectura .cascada__fila:first-child{border-top:0}\n.lectura__num{\n  display:grid;place-items:center;\n  width:22px;height:22px;margin-top:1px;\n  border-radius:50%;\n  background:var(--mitecho-acento);\n  box-shadow:inset 0 0 0 1.5px var(--tinta);\n  font:700 12px/1 var(--f-display);\n}\n.lectura__nota{font-size:11.5px;line-height:1.45;color:var(--tinta-2)}\n.lectura__nota b{font:600 12px/1.3 var(--f-display);color:var(--tinta)}\n.lectura__claves{\n  display:flex;justify-content:space-between;align-items:center;gap:20px;\n  margin-top:9px;\n  font-size:11px;color:var(--tinta-3);\n}\n.signos{display:flex;gap:14px;white-space:nowrap}\n.signos b{font:600 12px var(--f-mono);color:var(--tinta);margin-right:4px}\n.leyenda{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:5px 14px}\n.leyenda li{display:flex;align-items:center;gap:6px;white-space:nowrap}\n.leyenda i{display:block;width:16px;height:10px;border-radius:2px}\n\n/* Medidor explicado */\n.medidor-guia{\n  display:grid;\n  grid-template-columns:1.5fr 1fr;\n  gap:30px;\n  align-items:center;\n  padding:6px 18px;\n  border:1px solid var(--linea);\n  border-radius:12px;\n  background:var(--papel-alto);\n}\n.mg{display:flex;align-items:center;gap:10px;padding:30px 0}\n.mg > span{font:500 10.5px var(--f-mono);color:var(--mitecho-tenue)}\n.mg__pista{position:relative;flex:1;height:14px;border-radius:7px;background:var(--linea)}\n.mg__pista > i{position:absolute;inset:0 auto 0 0;border-radius:7px;background:var(--mitecho-azul)}\n.mg__pista > b{position:absolute;top:-6px;bottom:-6px;width:3px;margin-left:-1.5px;background:var(--tinta);border-radius:1px}\n.mg__tag{\n  position:absolute;\n  display:flex;\n  height:26px;\n  font-size:11px;line-height:1.2;color:var(--tinta-2);\n  white-space:nowrap;\n}\n.mg__tag strong{font:700 13px/1 var(--f-display);color:var(--tinta);margin-right:5px}\n.mg__tag--linea{bottom:100%;margin-bottom:6px;margin-left:-.75px;padding-left:7px;border-left:1.5px solid var(--tinta);align-items:flex-start}\n.mg__tag--valor{top:100%;margin-top:2px;transform:translateX(-100%);margin-left:.75px;padding-right:7px;border-right:1.5px solid var(--mitecho-azul);align-items:flex-end}\n.medidor-guia__regla{font-size:12px;line-height:1.5;color:var(--tinta-2)}\n.medidor-guia__regla b{display:block;margin-bottom:2px;font:600 12.5px/1.3 var(--f-display);color:var(--tinta)}\n\n.medidores--guia{margin-top:14px;gap:24px}\n.medidor__que{margin-top:8px;font-size:11.5px;line-height:1.45;color:var(--tinta)}\n.medidor__ejemplo{margin-top:7px;font-size:11.5px;line-height:1.45;color:var(--tinta-2)}\n.medidor__ejemplo b{font-weight:600;color:var(--tinta)}\n\n/* Glosario */\n.glosario{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:8px 24px;\n}\n.glosario div{padding-top:6px;border-top:1px solid var(--linea)}\n.glosario dt{font:600 12.5px/1.25 var(--f-display)}\n.glosario dd{margin-top:2px;font-size:11px;line-height:1.42;color:var(--tinta-3)}\n\n/* Ajuste al guardar o imprimir en tamaño carta */\n@page{size:letter;margin:0}\n@media print{\n  body{background:none}\n  .doc{display:block;padding:0}\n  .hoja{box-shadow:none;zoom:1;break-after:page;page-break-after:always}\n  .hoja:last-child{break-after:auto;page-break-after:auto}\n}\n";
